def rle(s: str) -> str:
    """Run-length encode s: each maximal run of one character becomes the character followed by the run length as a decimal string, including runs of length 1 (so 'abb' -> 'a1b2'). Empty string returns ''.
    """
    if not s:
        return ''

    encoded = ''
    count = 1
    for i in range(len(s)):
        if i + 1 < len(s) and s[i] == s[i + 1]:
            count += 1
        else:
            encoded += s[i] + str(count)
            count = 1

    return encoded
```

