def longest_arith_subseq(nums: list[int]) -> int:
    if len(nums) <= 2:
        return len(nums)

    # dp[i][diff] = length of longest arithmetic subsequence ending at index i with common difference diff
    # Using dictionary for each index to store differences and their corresponding lengths
    dp = [{} for _ in range(len(nums))]
    max_length = 2  # At least 2 for any list of length >= 2

    for i in range(1, len(nums)):
        for j in range(i):
            diff = nums[i] - nums[j]
            # If there was a subsequence ending at j with difference diff, extend it
            if diff in dp[j]:
                dp[i][diff] = dp[j][diff] + 1
            else:
                # Start a new subsequence of length 2
                dp[i][diff] = 2
            max_length = max(max_length, dp[i][diff])

    return max_length
```

