def longest_arith_subseq(nums: list[int]) -> int:
    if not nums:
        return 0
    n = len(nums)
    if n <= 2:
        return n
    # dp[i][d] = length of longest arithmetic subsequence ending at index i with difference d
    dp = [{} for _ in range(n)]
    max_len = 1
    for i in range(n):
        for j in range(i):
            diff = nums[i] - nums[j]
            # length ending at j with same diff, or 1 (just the pair)
            length = dp[j].get(diff, 1) + 1
            dp[i][diff] = max(dp[i].get(diff, 0), length)
            if length > max_len:
                max_len = length
    return max_len
