def count_paths(grid: list[str], k: int) -> int:
    MOD = 1000000007
    rows, cols = len(grid), len(grid[0])

    # If start or end is blocked, no path possible
    if grid[0][0] == '#' or grid[rows-1][cols-1] == '#':
        return 0

    # DP: dp[i][j][count] = number of ways to reach (i,j) with exactly 'count' '*' cells
    # Use dictionary for sparse states to avoid TLE
    from collections import defaultdict
    dp = defaultdict(lambda: defaultdict(int))

    # Initialize starting position
    start_star = 1 if grid[0][0] == '*' else 0
    if start_star <= k:
        dp[0][0][start_star] = 1

    # Fill DP table
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '#':
                continue
            # Current cell's star count
            cell_star = 1 if grid[i][j] == '*' else 0

            # Check from top
            if i > 0:
                for count in dp[i-1][j]:
                    new_count = count + cell_star
                    if new_count <= k:
                        dp[i][j][new_count] = (dp[i][j][new_count] + dp[i-1][j][count]) % MOD

            # Check from left
            if j > 0:
                for count in dp[i][j-1]:
                    new_count = count + cell_star
                    if new_count <= k:
