def count_paths(grid: list[str], k: int) -> int:
    MOD = 1000000007
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    if rows == 0 or cols == 0:
        return 0
    if grid[0][0] == '#' or grid[-1][-1] == '#':
        return 0

    # dp[r][c][s] = number of ways to reach (r,c) with exactly s stars
    # We'll use a 2D list of dicts to save memory, or a 3D list with max possible stars
    max_stars = min(rows + cols - 1, k)  # at most path length stars
    # But we need up to k, so allocate k+1 if k <= path length, else cap
    max_possible = min(k, rows + cols - 1)

    # Use 2D array of lists of size max_possible+1
    dp = [[[0]*(max_possible+1) for _ in range(cols)] for _ in range(rows)]

    start_star = 1 if grid[0][0] == '*' else 0
    if start_star <= max_possible:
        dp[0][0][start_star] = 1

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '#':
                continue
            for s in range(max_possible+1):
                ways = dp[r][c][s]
                if ways == 0:
                    continue
                # move right
                if c+1 < cols and grid[r][c+1] != '#':
                    ns = s + (1 if grid[r][c+1] == '*' else 0)
                    if ns <= max_possible:
                        dp[r][c+1][ns] = (dp[r][c+1][ns] + ways) % MOD
                # move down
                if r+1 < rows and grid[r+1][c] != '#':
                    ns = s + (1 if grid[r+1][c] == '*' else 0)
                    if ns <= max_possible:
                        dp[r+1][c][ns] = (dp[r+1][c][ns] + ways) % MOD

    if k > max_possible:
        return 0
    return dp[rows-1][cols-1][k] % MOD
