    for i in range(n):
        prefix[i + 1] = prefix[i] + stones[i]

    # dp[i][j] = min cost to merge piles from i to j (inclusive) into as few piles as possible
    # The target number of piles for interval [i, j] is (j - i) % (k - 1) + 1
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = float('inf')
            # Try all possible last merge points
            # We need to leave exactly (k-1) piles on the right to merge with the left part
            for m in range(i, j, k - 1):
                dp[i][j] = min(dp[i][j], dp[i][m] + dp[m + 1][j])
            # If we can merge the whole interval into one pile
            if (j - i) % (k - 1) == 0:
                dp[i][j] += prefix[j + 1] - prefix[i]

